-- HR Policy Request Management synthetic seed data
-- Generated with seed 20261022. Load tables in dependency order.
PRAGMA foreign_keys = ON;
BEGIN TRANSACTION;
CREATE TABLE Department(department_id TEXT PRIMARY KEY, department_name TEXT UNIQUE NOT NULL, cost_center TEXT UNIQUE NOT NULL, hr_partner_employee_id TEXT NOT NULL REFERENCES Employee(employee_id) DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE Employee(employee_id TEXT PRIMARY KEY, first_name TEXT NOT NULL, last_name TEXT NOT NULL, department_id TEXT NOT NULL REFERENCES Department(department_id), manager_employee_id TEXT REFERENCES Employee(employee_id), work_email TEXT UNIQUE NOT NULL, location TEXT NOT NULL, employment_type TEXT NOT NULL CHECK(employment_type IN ('Full-time','Part-time','Contractor')), role TEXT NOT NULL, hire_date TEXT NOT NULL, is_active INTEGER NOT NULL CHECK(is_active IN (0,1)));
CREATE TABLE Category(category_id TEXT PRIMARY KEY, category_name TEXT UNIQUE NOT NULL, default_queue TEXT NOT NULL, default_sla_hours INTEGER NOT NULL CHECK(default_sla_hours>0), sensitive_by_default INTEGER NOT NULL CHECK(sensitive_by_default IN (0,1)));
CREATE TABLE PolicyDocument(policy_id TEXT PRIMARY KEY, title TEXT NOT NULL, owner_department_id TEXT NOT NULL REFERENCES Department(department_id), category_id TEXT NOT NULL REFERENCES Category(category_id), audience TEXT NOT NULL, confidentiality TEXT NOT NULL, created_date TEXT NOT NULL, lifecycle_state TEXT NOT NULL);
CREATE TABLE PolicyVersion(policy_version_id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES PolicyDocument(policy_id), version_number INTEGER NOT NULL, effective_from TEXT NOT NULL, effective_to TEXT, status TEXT NOT NULL, content_summary TEXT NOT NULL, approved_by_employee_id TEXT NOT NULL REFERENCES Employee(employee_id), UNIQUE(policy_id,version_number), CHECK(effective_to IS NULL OR effective_to>=effective_from));
CREATE TABLE KnowledgeArticle(knowledge_article_id TEXT PRIMARY KEY, policy_id TEXT NOT NULL REFERENCES PolicyDocument(policy_id), current_policy_version_id TEXT NOT NULL REFERENCES PolicyVersion(policy_version_id), title TEXT NOT NULL, answer_snippet TEXT NOT NULL, audience TEXT NOT NULL, status TEXT NOT NULL, last_reviewed_date TEXT NOT NULL);
CREATE TABLE Ticket(ticket_id TEXT PRIMARY KEY, employee_id TEXT NOT NULL REFERENCES Employee(employee_id), department_id TEXT NOT NULL REFERENCES Department(department_id), category_id TEXT NOT NULL REFERENCES Category(category_id), subject TEXT NOT NULL, description TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL, priority TEXT NOT NULL, is_sensitive INTEGER NOT NULL, ambiguity_flag INTEGER NOT NULL, missing_context_flag INTEGER NOT NULL, intended_queue TEXT NOT NULL, current_queue TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES PolicyDocument(policy_id), requested_audience TEXT NOT NULL, closed_at TEXT, issue_type TEXT NOT NULL);
CREATE TABLE Message(message_id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES Ticket(ticket_id), sender_type TEXT NOT NULL, sender_employee_id TEXT REFERENCES Employee(employee_id), sent_at TEXT NOT NULL, message_type TEXT NOT NULL, body TEXT NOT NULL, is_internal INTEGER NOT NULL);
CREATE TABLE Assignment(assignment_id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES Ticket(ticket_id), queue_name TEXT NOT NULL, assigned_to_employee_id TEXT REFERENCES Employee(employee_id), assigned_at TEXT NOT NULL, assignment_reason TEXT NOT NULL, is_current INTEGER NOT NULL);
CREATE TABLE SLA(sla_id TEXT PRIMARY KEY, ticket_id TEXT UNIQUE NOT NULL REFERENCES Ticket(ticket_id), target_business_hours INTEGER NOT NULL, clock_start_at TEXT NOT NULL, due_at TEXT NOT NULL, stopped_at TEXT, sla_status TEXT NOT NULL, calendar_name TEXT NOT NULL, business_hours TEXT NOT NULL, issue_type TEXT NOT NULL);
CREATE TABLE Resolution(resolution_id TEXT PRIMARY KEY, ticket_id TEXT UNIQUE NOT NULL REFERENCES Ticket(ticket_id), resolved_at TEXT NOT NULL, resolution_code TEXT NOT NULL, resolution_summary TEXT NOT NULL, resolving_employee_id TEXT NOT NULL REFERENCES Employee(employee_id), customer_confirmed INTEGER NOT NULL, policy_version_id TEXT REFERENCES PolicyVersion(policy_version_id), unsupported_claim_flag INTEGER NOT NULL);
CREATE TABLE TicketEvent(event_id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES Ticket(ticket_id), event_type TEXT NOT NULL, event_at TEXT NOT NULL, from_value TEXT, to_value TEXT, actor_id TEXT NOT NULL);
CREATE TABLE MessagePolicyCitation(message_id TEXT NOT NULL REFERENCES Message(message_id), policy_version_id TEXT NOT NULL REFERENCES PolicyVersion(policy_version_id), citation_type TEXT NOT NULL, PRIMARY KEY(message_id,policy_version_id));
COMMIT;
